test('counts a 31-day month from the 1st and rounds to 2 decimals', function () {
  assert.deepEqual(code.simpleInterest({ principal: 10000, annualRate: 0.06, startDate: '2026-03-01', endDate: '2026-04-01' }), { days: 31, interest: 50.96 });
});
test('counts 29 February in a leap year and still divides by 365', function () {
  assert.deepEqual(code.simpleInterest({ principal: 10000, annualRate: 0.06, startDate: '2028-02-01', endDate: '2028-03-01' }), { days: 29, interest: 47.67 });
});
test('returns zero days and zero interest when the start date equals the end date', function () {
  assert.deepEqual(code.simpleInterest({ principal: 10000, annualRate: 0.06, startDate: '2026-03-01', endDate: '2026-03-01' }), { days: 0, interest: 0 });
});
test('counts one day one step above a zero-day period starting on the 1st', function () {
  assert.deepEqual(code.simpleInterest({ principal: 20000, annualRate: 0.1, startDate: '2026-03-01', endDate: '2026-03-02' }), { days: 1, interest: 5.48 });
});
test('counts one day from the last day of January to the next day', function () {
  assert.deepEqual(code.simpleInterest({ principal: 30000, annualRate: 0.1, startDate: '2026-01-31', endDate: '2026-02-01' }), { days: 1, interest: 8.22 });
});
test('counts a 30-day month from the 1st to the next 1st', function () {
  assert.deepEqual(code.simpleInterest({ principal: 10000, annualRate: 0.06, startDate: '2026-04-01', endDate: '2026-05-01' }), { days: 30, interest: 49.32 });
});
test('counts 28 days for non-leap February from the 1st', function () {
  assert.deepEqual(code.simpleInterest({ principal: 10000, annualRate: 0.06, startDate: '2026-02-01', endDate: '2026-03-01' }), { days: 28, interest: 46.03 });
});
test('counts one day from the last day of December to 1 January', function () {
  assert.deepEqual(code.simpleInterest({ principal: 40000, annualRate: 0.1, startDate: '2026-12-31', endDate: '2027-01-01' }), { days: 1, interest: 10.96 });
});
test('counts days for a period covering December and January', function () {
  assert.deepEqual(code.simpleInterest({ principal: 10000, annualRate: 0.06, startDate: '2026-12-15', endDate: '2027-01-10' }), { days: 26, interest: 42.74 });
});
test('counts the leap day when it is the first counted day', function () {
  assert.deepEqual(code.simpleInterest({ principal: 20000, annualRate: 0.1, startDate: '2028-02-29', endDate: '2028-03-01' }), { days: 1, interest: 5.48 });
});
test('counts the leap day when it falls in the middle of the period', function () {
  assert.deepEqual(code.simpleInterest({ principal: 10000, annualRate: 0.06, startDate: '2028-02-15', endDate: '2028-03-10' }), { days: 24, interest: 39.45 });
});
test('counts the leap day when it is the last counted day', function () {
  assert.deepEqual(code.simpleInterest({ principal: 60000, annualRate: 0.1, startDate: '2028-02-28', endDate: '2028-03-01' }), { days: 2, interest: 32.88 });
});
test('excludes the leap day when the end date is the leap day', function () {
  assert.deepEqual(code.simpleInterest({ principal: 60000, annualRate: 0.1, startDate: '2028-02-28', endDate: '2028-02-29' }), { days: 1, interest: 16.44 });
});
test('divides by 365 in a leap year when the period has no 29 February', function () {
  assert.deepEqual(code.simpleInterest({ principal: 10000, annualRate: 0.06, startDate: '2028-03-01', endDate: '2028-04-01' }), { days: 31, interest: 50.96 });
});
test('rounds up when the amount is just over an exact half', function () {
  assert.deepEqual(code.simpleInterest({ principal: 36700, annualRate: 0.01, startDate: '2026-04-30', endDate: '2026-05-01' }), { days: 1, interest: 1.01 });
});
test('throws a named error when the input has an unknown field', function () {
  assert.throws(function () {
    code.simpleInterest({ principal: 10000, annualRate: 0.06, currency: 'USD', startDate: '2026-03-01', endDate: '2026-04-01' });
  }, /^unknown field: currency$/);
});
